    uint32_t       s_part_bx0;                    /* main.c:4173  */
    uint32_t       s_part_by0;                    /* main.c:4173  */
    uint32_t       s_part_bx1;                    /* main.c:4173  */
    uint32_t       s_part_by1;                    /* main.c:4173  */
