    uint32_t       s_refq_state;                  /* main.c:5607 = 2u */
    uint32_t       s_refq_dark;                   /* main.c:5608  */
    uint32_t       s_refq_part;                   /* main.c:5609  */
    uint32_t       s_refq_cnt;                    /* main.c:5610  */
